import random
import itertools
from collections import deque

def has_short_cycle(graph, n, max_length=7):
    for start in range(n):
        dist = [-1] * n
        dist[start] = 0
        queue = deque([(start, -1)])
        while queue:
            u, par = queue.popleft()
            for v in graph[u]:
                if v == par:
                    continue
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append((v, u))
                elif dist[v] >= 0:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= max_length:
                        return True
    return False

